(function () {
  "use strict";

  /* ---- 可运行示范：构建时内联的整页示范，srcdoc 沙箱挂载 ---- */
  var DEMO_HTML = "<!DOCTYPE html>\r\n<html lang=\"zh-CN\">\r\n<head>\r\n<meta charset=\"UTF-8\">\r\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\r\n<title>示范：完井液体系智能优选与配方设计<\/title>\r\n<style>\n/* 示范页样式。运行在沙箱 iframe 里，随便写，不影响主站。 */\r\n:root{\r\n  --ink:#242b2e; --ink-2:#4d565b; --ink-3:#79828a;\r\n  --line:#e9e4d8; --jade:#2f7d6b; --jade-l:#e6f1ec;\r\n  --clay:#b26a39; --paper:#fbfaf6;\r\n}\r\n*{box-sizing:border-box}\r\nbody{\r\n  margin:0;padding:18px 20px 24px;background:var(--paper);color:var(--ink);\r\n  font-family:\"Inter\",\"PingFang SC\",\"Microsoft YaHei\",system-ui,sans-serif;\r\n  font-size:13px;line-height:1.7;\r\n}\r\n.panel{width:100%}\r\nh1{font-size:19px;margin:0 0 6px;letter-spacing:-.01em}\r\n.lead{margin:0 0 16px;color:var(--ink-2);font-size:12.5px;line-height:1.78}\r\n.ctl{display:flex;align-items:center;gap:14px;margin-bottom:9px}\r\n.ctl label{font-size:12px;color:var(--ink-2);display:flex;align-items:center;gap:7px;min-width:170px}\r\n.ctl output{font-family:ui-monospace,monospace;font-size:13px;color:var(--jade);font-weight:600}\r\n.ctl input[type=range]{flex:1;accent-color:var(--jade);height:18px}\r\nsvg{display:block;width:100%;height:auto;border:1px solid var(--line);border-radius:8px;background:#fff}\r\nsvg + svg{margin-top:-1px;border-top-left-radius:0;border-top-right-radius:0}\r\n.readouts{\r\n  display:grid;grid-template-columns:repeat(4,1fr);gap:1px;\r\n  background:var(--line);border:1px solid var(--line);border-radius:8px;overflow:hidden;\r\n  margin-top:12px;\r\n}\r\n.ro{background:#fff;padding:9px 12px}\r\n.ro .k{display:block;font-size:10px;color:var(--ink-3);letter-spacing:.06em}\r\n.ro b{font-family:ui-monospace,monospace;font-size:13px;font-weight:600}\r\n.ro b.ok{color:var(--jade)}\r\n.ro b.bad{color:var(--clay)}\r\n.note{margin:12px 0 0;font-size:12px;color:var(--ink-3);line-height:1.75}\r\n.note b{color:var(--ink)}\r\n\r\n/* 证据清单表 */\r\n.tbl{\r\n  width:100%;border-collapse:collapse;margin-top:12px;font-size:11.5px;\r\n  background:#fff;border:1px solid var(--line);border-radius:8px;overflow:hidden;\r\n}\r\n.tbl th{\r\n  text-align:left;font-weight:600;font-size:10.5px;color:var(--ink-3);letter-spacing:.05em;\r\n  background:#f7f5ef;padding:7px 9px;border-bottom:1px solid var(--line);white-space:nowrap;\r\n}\r\n.tbl td{padding:6px 9px;border-bottom:1px solid #f2efe6;color:var(--ink-2);font-family:ui-monospace,monospace;white-space:nowrap}\r\n.tbl td.nm{font-family:inherit;color:var(--ink)}\r\n.tbl tr:last-child td{border-bottom:none}\r\n.tbl caption{caption-side:top;text-align:left;font-size:11.5px;color:var(--ink-3);padding:0 0 6px}\r\n\r\n/* 通用小组件 */\r\n.dot{display:inline-block;width:8px;height:8px;border-radius:50%;margin-right:6px;vertical-align:1px}\r\n.btnrow{display:flex;gap:8px;flex-wrap:wrap;margin:12px 0 2px}\r\n.btnrow button{\r\n  font:inherit;font-size:12px;padding:5px 12px;border:1px solid var(--line);\r\n  background:#fff;color:var(--ink-2);border-radius:6px;cursor:pointer;\r\n}\r\n.btnrow button:hover{border-color:var(--jade);color:var(--jade)}\r\n.btnrow button.on{background:var(--jade-l);border-color:var(--jade);color:var(--jade)}\r\n.legend{display:flex;gap:14px;flex-wrap:wrap;margin-top:10px;font-size:11.5px;color:var(--ink-3)}\r\n.legend i{display:inline-block;width:10px;height:10px;border-radius:2px;margin-right:5px;vertical-align:-1px}\r\n\n/* 智能方法区块 */\n.meth{margin:14px 0 0;border:1px solid var(--line,#e2dccd);border-left:3px solid var(--jade,#2f7d6b);border-radius:9px;background:var(--jade-l,#f4f6f0)}.meth-h{font-size:11.5px;font-weight:700;color:var(--jade,#2f7d6b);letter-spacing:.05em;padding:9px 15px 2px}.meth-g{display:flex;flex-wrap:wrap;padding:0 0 9px}.meth-g>div{flex:1 1 200px;min-width:185px;padding:3px 15px}.meth-g>div+div{border-left:1px dashed var(--line,#e2dccd)}.meth-g b{display:block;font-size:11px;color:var(--clay,#8a6a3a);margin:3px 0 2px}.meth-g ul{margin:0;padding-left:14px}.meth-g li{font-size:11.6px;line-height:1.62;color:var(--ink-2,#3d4a48);margin:1px 0}\n\n<\/style>\r\n<style>\n/* ===== 排版统一（站点构建注入）：标题 / 导语 / 说明 分层，行距字号全站一致 ===== */\nbody{font-size:13px;line-height:1.75}\nh1{font-size:19px;line-height:1.45;margin:0 0 10px;padding-bottom:9px;border-bottom:1px solid var(--line)}\nh2{font-size:15px;line-height:1.5;margin:24px 0 10px;padding-top:14px;border-top:1px solid var(--line)}\nh3{font-size:13.5px;line-height:1.5;margin:18px 0 8px}\np{margin:9px 0;line-height:1.85}\n.lead{font-size:13px;line-height:1.9;margin:0 0 16px}\n.note{font-size:12.5px;line-height:1.85;margin:14px 0 0}\n.note b{color:var(--ink)}\nli{line-height:1.85;margin:4px 0}\ntd,th{line-height:1.65}\ncaption{line-height:1.7}\nsvg{margin-top:12px}\nsvg + svg{margin-top:-1px}\n/* ===== 示范页分区板块（构建注入）：内容按职责分块，不再杂糅 =====\n     每块都是实卡：白底 + 明显描边 + 浮起阴影；画布底色加深反衬 */\nbody{background:#e2dac6}\n.blk{margin-top:24px}\n.blk-card{background:#fff;border:1px solid #a89a7d;border-radius:10px;padding:13px 16px 9px;box-shadow:0 2px 4px rgba(80,70,50,.13),0 6px 18px rgba(80,70,50,.15)}\n.blk-card>.ctl:last-child{margin-bottom:8px}\n.blk-raw{background:#fff;border:1px solid #a89a7d;border-radius:10px;box-shadow:0 2px 4px rgba(80,70,50,.13),0 6px 18px rgba(80,70,50,.15);overflow:hidden;padding-top:6px}\n.blk-raw>svg{margin-top:0;border:0;border-radius:0;background:transparent}\n.blk-raw>svg:first-child{overflow:visible}\n.blk-raw>svg rect:first-of-type{fill:#fff}\n.blk-raw>svg+svg{border-top:1px solid #c4b89c}\n.blk-raw .readouts,.blk-raw .tbl{margin-top:0;border:0;border-radius:0;box-shadow:none}\n.blk-raw .tbl{border-top:1px solid var(--line)}\n.blk-note{background:#f1ecdf;border:1px solid #a89a7d;border-radius:10px;padding:11px 16px;box-shadow:0 1px 3px rgba(80,70,50,.1)}\n.blk-note .note{margin:0}\n.blk-note .legend{margin:0}\n<\/style>\n<\/head>\r\n<body>\r\n<div class=\"panel\">\r\n  <h1>完井液体系智能优选 · 伤害构成与配方寻优<\/h1>\r\n  <p class=\"lead\">产能低的时候真正难的是回答「伤害到底来自哪里」。这里把伤害拆成五类机理，用图谱给出的配伍性做可行域剪枝，\r\n  再在滤失与预算约束内做配方寻优——<b>输出的是成本—恢复率的取舍曲线，不是一个数字<\/b>。<\/p><div class=\"meth\"><div class=\"meth-h\">智能方法 · 为什么起作用<\/div><div class=\"meth-g\"><div><b>用了什么方法<\/b><ul><li>知识图谱推理（体系 → 伤害机理）<\/li><li>约束寻优<\/li><li>岩心驱替实验设计<\/li><\/ul><\/div><div><b>为什么起作用<\/b><ul><li>五类伤害由配方与工况共同决定，图谱把「添加剂 → 机理 → 禁忌」显式化<\/li><li>密度、流变、相容是硬门槛，先筛可行再最小化总伤害<\/li><\/ul><\/div><div><b>在示范里怎么看<\/b><ul><li>调粘土含量与温度，看伤害构成与推荐配方同步变<\/li><\/ul><\/div><\/div><\/div>\r\n\r\n  <div class=\"ctl\">\r\n    <label>储层粘土含量 <output id=\"out-clay\">14 %<\/output><\/label>\r\n    <input type=\"range\" id=\"clay\" min=\"4\" max=\"28\" step=\"1\" value=\"14\">\r\n  <\/div>\r\n  <div class=\"ctl\">\r\n    <label>地层温度 <output id=\"out-temp\">120 ℃<\/output><\/label>\r\n    <input type=\"range\" id=\"temp\" min=\"60\" max=\"175\" step=\"5\" value=\"120\">\r\n  <\/div>\r\n  <div class=\"ctl\">\r\n    <label>作业压差 <output id=\"out-dp\">12 MPa<\/output><\/label>\r\n    <input type=\"range\" id=\"dp\" min=\"2\" max=\"25\" step=\"1\" value=\"12\">\r\n  <\/div>\r\n  <div class=\"ctl\">\r\n    <label>暂堵剂加量 <output id=\"out-fps\">1.5 %<\/output><\/label>\r\n    <input type=\"range\" id=\"fps\" min=\"0\" max=\"5\" step=\"0.25\" value=\"1.5\">\r\n  <\/div>\r\n  <div class=\"ctl\">\r\n    <label>防膨剂加量 <output id=\"out-stab\">0.8 %<\/output><\/label>\r\n    <input type=\"range\" id=\"stab\" min=\"0\" max=\"3\" step=\"0.1\" value=\"0.8\">\r\n  <\/div>\r\n  <div class=\"ctl\">\r\n    <label>单方预算上限 <output id=\"out-bg\">2.8<\/output><\/label>\r\n    <input type=\"range\" id=\"bg\" min=\"1.5\" max=\"5\" step=\"0.1\" value=\"2.8\">\r\n  <\/div>\r\n  <div class=\"btnrow\" id=\"fluidrow\"><\/div>\r\n\r\n  <svg id=\"dm\" viewBox=\"0 0 720 200\" role=\"img\" aria-label=\"伤害机理构成\"><\/svg>\r\n\r\n  <svg id=\"kg\" viewBox=\"0 0 720 220\" role=\"img\" aria-label=\"敏感档与体系的配伍矩阵与剪枝清单\"><\/svg>\r\n\r\n  <svg id=\"pf\" viewBox=\"0 0 720 260\" role=\"img\" aria-label=\"候选配方的成本与渗透率恢复率关系\"><\/svg>\r\n\r\n  <div class=\"legend\">\r\n    <span><i style=\"background:#b9c6cf\"><\/i>可行候选配方<\/span>\r\n    <span><i style=\"background:#41699b\"><\/i>帕累托前沿（同成本下恢复率最高）<\/span>\r\n    <span><i style=\"background:#242b2e\"><\/i>当前配方<\/span>\r\n    <span><i style=\"background:#2f7d6b\"><\/i>预算内最优<\/span>\r\n  <\/div>\r\n\r\n  <div class=\"readouts\">\r\n    <div class=\"ro\"><span class=\"k\">渗透率恢复值<\/span><b id=\"ro-krec\">—<\/b><\/div>\r\n    <div class=\"ro\"><span class=\"k\">主要伤害机理<\/span><b id=\"ro-main\">—<\/b><\/div>\r\n    <div class=\"ro\"><span class=\"k\">滤失 / 单方成本<\/span><b id=\"ro-cons\">—<\/b><\/div>\r\n    <div class=\"ro\"><span class=\"k\">预算内还可拿回<\/span><b id=\"ro-gain\">—<\/b><\/div>\r\n  <\/div>\r\n\r\n  <p class=\"note\" id=\"note\"><\/p>\r\n<\/div>\r\n<script>\n/* =========================================================\r\n   完井液体系智能优选与配方设计 · 示范脚本（整页模式，沙箱 iframe）\r\n   ---------------------------------------------------------\r\n   ① 知识图谱层：按粘土含量划敏感档，查「敏感档 × 体系」配伍矩阵，\r\n     得到配伍性与可用体系（耐温/配伍做可行域剪枝）；\r\n   ② 伤害模型：把损失拆成五类机理 → 渗透率恢复值 Krec；\r\n   ③ 在体系 × 暂堵剂 × 防膨剂的网格上枚举，用滤失与预算做约束，\r\n     给出帕累托前沿和预算内最优。\r\n   注：这是演示用的降阶模型，不是岩心驱替实验结果。\r\n   ========================================================= */\r\n(function () {\r\n  \"use strict\";\r\n\r\n  /* ---------- 0. 体系与知识图谱 ---------- */\r\n  /* hyd 滤液使粘土水化的能力 · inv 侵入伤害 · emu 乳化倾向 · scale 结垢/化学不配伍\r\n     Tmax 耐温上限 ℃ · cake 滤饼建造能力 · flBase 基础滤失 mL · cost 相对单方成本 */\r\n  var FLUIDS = [\r\n    { nm: \"低固相水基\", hyd: 1.00, inv: 0.90, emu: 0.25, scale: 0.55, Tmax: 130, cake: 0.55, flBase: 5.5, cost: 1.00 },\r\n    { nm: \"清洁盐水\", hyd: 0.72, inv: 0.55, emu: 0.15, scale: 0.75, Tmax: 150, cake: 0.35, flBase: 7.0, cost: 1.60 },\r\n    { nm: \"油基\", hyd: 0.15, inv: 0.30, emu: 0.85, scale: 0.30, Tmax: 165, cake: 0.80, flBase: 3.2, cost: 3.20 },\r\n    { nm: \"合成基\", hyd: 0.22, inv: 0.35, emu: 0.55, scale: 0.35, Tmax: 170, cake: 0.72, flBase: 3.6, cost: 2.60 },\r\n    { nm: \"弱凝胶暂堵\", hyd: 0.85, inv: 0.50, emu: 0.20, scale: 0.50, Tmax: 120, cake: 0.92, flBase: 2.4, cost: 1.90 }\r\n  ];\r\n\r\n  /* 知识图谱：敏感档（由粘土含量划分）→ 各体系配伍性 0–1 */\r\n  var CLUSTERS = [\r\n    { nm: \"低敏\", lo: 0, hi: 8 },\r\n    { nm: \"中敏\", lo: 8, hi: 15 },\r\n    { nm: \"高敏\", lo: 15, hi: 22 },\r\n    { nm: \"特高敏\", lo: 22, hi: 99 }\r\n  ];\r\n  var COMPAT = [\r\n    [0.92, 0.95, 0.85, 0.88, 0.90],\r\n    [0.80, 0.92, 0.88, 0.90, 0.85],\r\n    [0.62, 0.88, 0.90, 0.92, 0.78],\r\n    [0.45, 0.80, 0.92, 0.95, 0.70]\r\n  ];\r\n  /* 案例库：每个「敏感档 × 体系」组合的历史应用井次（用于提示证据是否够） */\r\n  var HIST = [\r\n    [46, 22, 5, 8, 14],\r\n    [38, 31, 9, 12, 17],\r\n    [19, 24, 14, 15, 11],\r\n    [7, 12, 11, 9, 6]\r\n  ];\r\n\r\n  var MECH = [\r\n    { nm: \"粘土水化 / 分散\", c: \"#41699b\" },\r\n    { nm: \"滤液与固相侵入\", c: \"#2f7d6b\" },\r\n    { nm: \"乳化 / 润湿反转\", c: \"#b26a39\" },\r\n    { nm: \"结垢 / 化学不配伍\", c: \"#c9613f\" },\r\n    { nm: \"高温降解损失\", c: \"#8d9298\" }\r\n  ];\r\n\r\n  var FL_LIMIT = 8.0;   /* API 滤失上限 mL */\r\n\r\n  function clusterOf(clay) {\r\n    for (var i = 0; i < CLUSTERS.length; i++) if (clay >= CLUSTERS[i].lo && clay < CLUSTERS[i].hi) return i;\r\n    return CLUSTERS.length - 1;\r\n  }\r\n\r\n  /* ---------- 1. 伤害模型 ---------- */\r\n  function damage(fi, clay, T, dp, fps, stab) {\r\n    var f = FLUIDS[fi];\r\n    var cl = clusterOf(clay);\r\n    var compat = COMPAT[cl][fi];\r\n    var cs = 1.30 - compat * 0.75;              /* 配伍因子：越配伍，各类伤害越小 */\r\n    var plug = 1 - Math.exp(-(0.35 + f.cake) * fps / 1.8);   /* 暂堵形成的滤饼封堵率 */\r\n    var inhib = 0.85 * (1 - Math.exp(-stab / 1.6));          /* 防膨剂抑制效率 */\r\n\r\n    var dClay = 2.04 * clay * f.hyd * (1 - inhib) * cs;\r\n    var dInv = 20 * (dp / 25) * f.inv * (1 - plug) * cs;\r\n    var dEmu = 9 * f.emu * (0.4 + dp / 25) * cs;\r\n    var dScale = 9 * f.scale * (T / 150) * cs;\r\n    var dTherm = 8 * Math.max(0, T - f.Tmax) / 15;\r\n\r\n    var arr = [dClay, dInv, dEmu, dScale, dTherm];\r\n    var sum = 0;\r\n    arr.forEach(function (v) { sum += v; });\r\n    return {\r\n      d: arr, sum: sum, krec: Math.max(25, Math.min(100, 100 - sum)), compat: compat,\r\n      fl: f.flBase * (0.5 + dp / 25) * (1 - 0.65 * plug) + 0.8,\r\n      cost: f.cost + 0.42 * fps + 1.10 * stab\r\n    };\r\n  }\r\n\r\n  function feasible(fi, T, cost, fl, budget) {\r\n    return T <= FLUIDS[fi].Tmax + 10 && cost <= budget + 1e-9 && fl <= FL_LIMIT + 1e-9;\r\n  }\r\n\r\n  /* ---------- 2. DOM ---------- */\r\n  var el = function (id) { return document.getElementById(id); };\r\n  var clayIn = el(\"clay\"), tempIn = el(\"temp\"), dpIn = el(\"dp\"),\r\n    fpsIn = el(\"fps\"), stabIn = el(\"stab\"), bgIn = el(\"bg\");\r\n  var dm = el(\"dm\"), pf = el(\"pf\"), note = el(\"note\"), rowEl = el(\"fluidrow\");\r\n  var kgSvg = el(\"kg\");\r\n  var tB = function (str) { return \"<tspan font-weight='600'>\" + str + \"<\/tspan>\"; };\r\n  var cur = 0;\r\n\r\n  var btns = FLUIDS.map(function (f, i) {\r\n    var b = document.createElement(\"button\");\r\n    b.type = \"button\";\r\n    b.textContent = f.nm;\r\n    b.className = i === cur ? \"on\" : \"\";\r\n    b.addEventListener(\"click\", function () { cur = i; draw(); });\r\n    rowEl.appendChild(b);\r\n    return b;\r\n  });\r\n\r\n  /* ---------- 3. 绘图 ---------- */\r\n  function drawMech(res) {\r\n    var W = 720, H = 200, ML = 168, MR = 108, PT = 14, rh = 32;\r\n    var maxV = 1;\r\n    res.d.forEach(function (v) { maxV = Math.max(maxV, v); });\r\n    maxV = Math.ceil(maxV / 5) * 5;\r\n    var bw = (W - ML - MR);\r\n    var s = '<text x=\"' + ML + '\" y=\"' + (PT - 2) + '\" font-size=\"9.5\" fill=\"#79828a\">' +\r\n      '各类机理造成的渗透率损失（百分点，合计 ' + res.sum.toFixed(1) + '）<\/text>';\r\n    res.d.forEach(function (v, i) {\r\n      var y = PT + 6 + i * rh;\r\n      var w = v / maxV * bw;\r\n      s += '<text x=\"' + (ML - 9) + '\" y=\"' + (y + 15) + '\" font-size=\"11\" fill=\"#242b2e\" text-anchor=\"end\">' + MECH[i].nm + '<\/text>';\r\n      s += '<rect x=\"' + ML + '\" y=\"' + y + '\" width=\"' + bw + '\" height=\"20\" fill=\"#f4f2e9\" rx=\"2\"/>';\r\n      s += '<rect x=\"' + ML + '\" y=\"' + y + '\" width=\"' + Math.max(0.6, w).toFixed(1) + '\" height=\"20\" fill=\"' + MECH[i].c + '\" opacity=\".88\" rx=\"2\"/>';\r\n      s += '<text x=\"' + (ML + bw + 7) + '\" y=\"' + (y + 14) + '\" font-size=\"10.5\" fill=\"#4d565b\" font-family=\"monospace\">' +\r\n        v.toFixed(1) + '<\/text>';\r\n    });\r\n    dm.innerHTML = s;\r\n  }\r\n\r\n  /* ---------- 知识图谱层：配伍矩阵 + 剪枝清单 ---------- */\r\n  function drawKg(cl, T, budget, curFi) {\r\n    var shortNm = [\"低固相\", \"清洁盐水\", \"油基\", \"合成基\", \"弱凝胶\"];\r\n    var s = \"\";\r\n    s += '<text x=\"14\" y=\"18\" font-size=\"10.5\" fill=\"#79828a\">知识图谱层：敏感档 × 体系的配伍性（格内为配伍性 / 历史井次），深色格＝本井所在档<\/text>';\r\n    var x0 = 118, colW = 100, y0 = 46, rowH = 32;\r\n    shortNm.forEach(function (nm, j) {\r\n      s += '<text x=\"' + (x0 + j * colW + colW / 2) + '\" y=\"38\" font-size=\"9\" fill=\"#4d565b\" text-anchor=\"middle\">' + nm + '<\/text>';\r\n    });\r\n    CLUSTERS.forEach(function (c, i) {\r\n      s += '<text x=\"' + (x0 - 8) + '\" y=\"' + (y0 + i * rowH + 20) + '\" font-size=\"9.5\" fill=\"' +\r\n        (i === cl ? \"#242b2e\" : \"#79828a\") + '\" text-anchor=\"end\">' + c.nm + ' ' + c.lo + '–' +\r\n        (c.hi > 90 ? \"28\" : c.hi) + '%<\/text>';\r\n      FLUIDS.forEach(function (f, j) {\r\n        var cp = COMPAT[i][j], n = HIST[i][j];\r\n        var op = (0.12 + (cp - 0.4) / 0.6 * 0.8).toFixed(2);\r\n        var isCur = (i === cl && j === curFi);\r\n        s += '<rect x=\"' + (x0 + j * colW) + '\" y=\"' + (y0 + i * rowH) + '\" width=\"' + (colW - 3) + '\" height=\"' +\r\n          (rowH - 3) + '\" rx=\"3\" fill=\"#2f7d6b\" opacity=\"' + op + '\"' +\r\n          (isCur ? ' stroke=\"#242b2e\" stroke-width=\"1.6\"' : (i === cl ? ' stroke=\"#e2ded0\"' : '')) + '/>';\r\n        s += '<text x=\"' + (x0 + j * colW + 8) + '\" y=\"' + (y0 + i * rowH + 14) + '\" font-size=\"9.5\" fill=\"' +\r\n          (cp > 0.75 ? \"#fff\" : \"#242b2e\") + '\">' + (cp * 100).toFixed(0) + '%<\/text>';\r\n        s += '<text x=\"' + (x0 + j * colW + 8) + '\" y=\"' + (y0 + i * rowH + 26) + '\" font-size=\"8.5\" fill=\"' +\r\n          (cp > 0.75 ? \"#e4efea\" : \"#5a636a\") + '\">n=' + n + (n < 10 ? \"（证据少）\" : \"\") + '<\/text>';\r\n      });\r\n    });\r\n    /* 剪枝清单 */\r\n    s += '<line x1=\"14\" y1=\"' + (y0 + CLUSTERS.length * rowH + 6) + '\" x2=\"706\" y2=\"' + (y0 + CLUSTERS.length * rowH + 6) +\r\n      '\" stroke=\"#e2ded0\"/>';\r\n    s += '<text x=\"14\" y=\"' + (y0 + CLUSTERS.length * rowH + 24) + '\" font-size=\"10\" fill=\"#4d565b\">剪枝清单（发生在寻优之前）：<\/text>';\r\n    var bx = 176;\r\n    FLUIDS.forEach(function (f, j) {\r\n      var okT = T <= f.Tmax + 10, okB = f.cost <= budget;\r\n      var pass = okT && okB;\r\n      var col = pass ? \"#2f7d6b\" : \"#c9613f\";\r\n      s += '<rect x=\"' + (bx + j * 106) + '\" y=\"' + (y0 + CLUSTERS.length * rowH + 12) + '\" width=\"100\" height=\"20\" rx=\"3\" fill=\"' +\r\n        col + '\" opacity=\"' + (pass ? 0.15 : 0.12) + '\" stroke=\"' + col + '\"/>';\r\n      s += '<text x=\"' + (bx + j * 106 + 6) + '\" y=\"' + (y0 + CLUSTERS.length * rowH + 26) + '\" font-size=\"8.5\" fill=\"' +\r\n        (pass ? \"#2f7d6b\" : \"#c9613f\") + '\">' + shortNm[j] + ' ' + (pass ? \"可用\" : (!okT ? \"超耐温\" : \"超预算\")) + '<\/text>';\r\n    });\r\n    s += '<text x=\"14\" y=\"' + (y0 + CLUSTERS.length * rowH + 44) + '\" font-size=\"10\" fill=\"#4d565b\">配伍性与耐温是' +\r\n      tB(\"硬约束\") + '：不满足的体系根本不进候选集——所以后面的寻优只需在剩下的组合里比成本与恢复率。<\/text>';\r\n    kgSvg.innerHTML = s;\r\n  }\r\n\r\n  function drawPareto(cands, best, curPt, budget) {\r\n    var W = 720, H = 260, ML = 52, MR = 16, MT = 16, MB = 34;\r\n    var x0 = 1e9, x1 = -1e9, y0 = 1e9, y1 = -1e9;\r\n    cands.forEach(function (p) {\r\n      x0 = Math.min(x0, p.cost); x1 = Math.max(x1, p.cost);\r\n      y0 = Math.min(y0, p.krec); y1 = Math.max(y1, p.krec);\r\n    });\r\n    if (curPt) {\r\n      x0 = Math.min(x0, curPt.cost); x1 = Math.max(x1, curPt.cost);\r\n      y0 = Math.min(y0, curPt.krec); y1 = Math.max(y1, curPt.krec);\r\n    }\r\n    var px = (x1 - x0) * 0.06 || 0.2, py = (y1 - y0) * 0.08 || 1;\r\n    x0 -= px; x1 += px; y0 -= py; y1 += py;\r\n    var X = function (v) { return ML + (v - x0) / (x1 - x0) * (W - ML - MR); };\r\n    var Y = function (v) { return MT + (1 - (v - y0) / (y1 - y0)) * (H - MT - MB); };\r\n\r\n    var s = \"\";\r\n    [0, 0.5, 1].forEach(function (f) {\r\n      var v = y0 + (y1 - y0) * f;\r\n      s += '<line x1=\"' + ML + '\" y1=\"' + Y(v).toFixed(1) + '\" x2=\"' + (W - MR) + '\" y2=\"' + Y(v).toFixed(1) + '\" stroke=\"#efece1\"/>';\r\n      s += '<text x=\"' + (ML - 7) + '\" y=\"' + (Y(v) + 3).toFixed(1) + '\" font-size=\"9\" fill=\"#9ba3a9\" text-anchor=\"end\" ' +\r\n        'font-family=\"monospace\">' + v.toFixed(0) + '<\/text>';\r\n    });\r\n    /* 预算竖线 */\r\n    s += '<line x1=\"' + X(budget).toFixed(1) + '\" y1=\"' + MT + '\" x2=\"' + X(budget).toFixed(1) + '\" y2=\"' + (H - MB) +\r\n      '\" stroke=\"#c9613f\" stroke-width=\"1\" stroke-dasharray=\"4 3\"/>';\r\n    s += '<text x=\"' + (X(budget) - 5).toFixed(1) + '\" y=\"' + (MT + 10) + '\" font-size=\"9.5\" fill=\"#c9613f\" text-anchor=\"end\">预算上限<\/text>';\r\n\r\n    /* 全部候选 */\r\n    cands.forEach(function (p) {\r\n      s += '<circle cx=\"' + X(p.cost).toFixed(1) + '\" cy=\"' + Y(p.krec).toFixed(1) + '\" r=\"2.1\" fill=\"#b9c6cf\" opacity=\".75\"/>';\r\n    });\r\n    /* 帕累托前沿 */\r\n    var d = \"\", front = [];\r\n    cands.forEach(function (p) { front.push(p); });\r\n    front.sort(function (a, b) { return a.cost - b.cost; });\r\n    var mk = -1, line = [];\r\n    front.forEach(function (p) {\r\n      if (p.krec > mk + 1e-9) { mk = p.krec; line.push(p); }\r\n    });\r\n    line.forEach(function (p, i) {\r\n      d += (i ? \"L\" : \"M\") + X(p.cost).toFixed(1) + \" \" + Y(p.krec).toFixed(1);\r\n    });\r\n    s += '<path d=\"' + d + '\" fill=\"none\" stroke=\"#41699b\" stroke-width=\"1.5\" stroke-linejoin=\"round\"/>';\r\n    line.forEach(function (p) {\r\n      s += '<circle cx=\"' + X(p.cost).toFixed(1) + '\" cy=\"' + Y(p.krec).toFixed(1) + '\" r=\"2.8\" fill=\"#41699b\"/>';\r\n    });\r\n    /* 当前配方 */\r\n    if (curPt) {\r\n      s += '<rect x=\"' + (X(curPt.cost) - 4).toFixed(1) + '\" y=\"' + (Y(curPt.krec) - 4).toFixed(1) +\r\n        '\" width=\"8\" height=\"8\" fill=\"#242b2e\"/>';\r\n      s += '<text x=\"' + (X(curPt.cost) + 9).toFixed(1) + '\" y=\"' + (Y(curPt.krec) + 14).toFixed(1) +\r\n        '\" font-size=\"10\" fill=\"#242b2e\">当前<\/text>';\r\n    }\r\n    /* 预算内最优 */\r\n    s += '<circle cx=\"' + X(best.cost).toFixed(1) + '\" cy=\"' + Y(best.krec).toFixed(1) + '\" r=\"5\" fill=\"none\" ' +\r\n      'stroke=\"#2f7d6b\" stroke-width=\"1.6\"/>';\r\n    s += '<text x=\"' + (X(best.cost) + 8).toFixed(1) + '\" y=\"' + (Y(best.krec) - 6).toFixed(1) +\r\n      '\" font-size=\"10\" fill=\"#2f7d6b\">最优 ' + best.krec.toFixed(1) + '%<\/text>';\r\n    s += '<text x=\"' + (W - MR) + '\" y=\"' + (H - 8) + '\" font-size=\"9.5\" fill=\"#4d565b\" text-anchor=\"end\">单方成本（相对指数）→<\/text>';\r\n    s += '<text x=\"' + (ML - 7) + '\" y=\"' + (MT - 4) + '\" font-size=\"9.5\" fill=\"#4d565b\" text-anchor=\"end\">↑ 渗透率恢复值 %<\/text>';\r\n    pf.innerHTML = s;\r\n  }\r\n\r\n  /* ---------- 4. 主流程 ---------- */\r\n  function draw() {\r\n    var clay = Number(clayIn.value), T = Number(tempIn.value), dp = Number(dpIn.value),\r\n      fps = Number(fpsIn.value), stab = Number(stabIn.value), budget = Number(bgIn.value);\r\n\r\n    el(\"out-clay\").textContent = clay + \" %\";\r\n    el(\"out-temp\").textContent = T + \" ℃\";\r\n    el(\"out-dp\").textContent = dp + \" MPa\";\r\n    el(\"out-fps\").textContent = fps.toFixed(2) + \" %\";\r\n    el(\"out-stab\").textContent = stab.toFixed(1) + \" %\";\r\n    el(\"out-bg\").textContent = budget.toFixed(1);\r\n    btns.forEach(function (b, i) { b.className = i === cur ? \"on\" : \"\"; });\r\n\r\n    var cl = clusterOf(clay);\r\n    var res = damage(cur, clay, T, dp, fps, stab);\r\n    var overTemp = T > FLUIDS[cur].Tmax + 10;\r\n\r\n    /* 枚举：体系 × 暂堵剂 × 防膨剂 */\r\n    var cands = [], best = null;\r\n    for (var fi = 0; fi < FLUIDS.length; fi++) {\r\n      for (var a = 0; a <= 5.0001; a += 0.5) {\r\n        for (var b = 0; b <= 3.0001; b += 0.25) {\r\n          var r = damage(fi, clay, T, dp, a, b);\r\n          if (!feasible(fi, T, r.cost, r.fl, budget)) continue;\r\n          var pt = { fi: fi, fps: a, stab: b, cost: r.cost, krec: r.krec, fl: r.fl, compat: r.compat };\r\n          cands.push(pt);\r\n          if (!best || r.krec > best.krec + 1e-9 ||\r\n            (Math.abs(r.krec - best.krec) <= 1e-9 && r.cost < best.cost)) best = pt;\r\n        }\r\n      }\r\n    }\r\n\r\n    drawMech(res);\r\n    drawKg(cl, T, budget, cur);\r\n    drawPareto(cands, best, { cost: res.cost, krec: res.krec }, budget);\r\n\r\n    /* 读数 */\r\n    var kEl = el(\"ro-krec\");\r\n    kEl.textContent = res.krec.toFixed(1) + \" %\";\r\n    kEl.className = res.krec >= 80 ? \"ok\" : (res.krec >= 70 ? \"\" : \"bad\");\r\n    var mainIdx = 0, mv = -1;\r\n    res.d.forEach(function (v, i) { if (v > mv) { mv = v; mainIdx = i; } });\r\n    el(\"ro-main\").textContent = MECH[mainIdx].nm + \" \" + (mv / res.sum * 100).toFixed(0) + \"%\";\r\n    var cEl = el(\"ro-cons\");\r\n    cEl.textContent = res.fl.toFixed(1) + \" mL / \" + res.cost.toFixed(2);\r\n    cEl.className = (res.fl <= FL_LIMIT && res.cost <= budget) ? \"ok\" : \"bad\";\r\n    var gain = (best ? best.krec - res.krec : 0);\r\n    var gEl = el(\"ro-gain\");\r\n    gEl.textContent = (gain >= 0 ? \"+\" : \"\") + gain.toFixed(1) + \" 个百分点\";\r\n    gEl.className = gain > 2 ? \"ok\" : \"\";\r\n\r\n    /* 解说 */\r\n    var msg = \"当前：\" + FLUIDS[cur].nm + \" + 暂堵 \" + fps.toFixed(2) + \"% + 防膨 \" + stab.toFixed(1) + \"%，\" +\r\n      \"恢复值 <b>\" + res.krec.toFixed(1) + \"%<\/b>。知识图谱把本井判为 <b>\" + CLUSTERS[cl].nm +\r\n      \"<\/b>（粘土 \" + clay + \"%），该体系配伍性 <b>\" + (res.compat * 100).toFixed(0) + \"%<\/b>，\" +\r\n      \"案例库里有 <b>\" + HIST[cl][cur] + \" 井次<\/b>同类组合的记录\";\r\n    msg += HIST[cl][cur] < 10 ? \"——<b>证据偏少<\/b>，这个推荐要打个折扣看。\" : \"，属于有支撑的组合。\";\r\n    if (overTemp) {\r\n      msg += \" 但地层温度 \" + T + \" ℃ 已超过该体系耐温上限 \" + FLUIDS[cur].Tmax +\r\n        \" ℃：<b>这个候选在高温段会降解失效<\/b>，图谱应当先把它剪掉。\";\r\n    }\r\n    if (best) {\r\n      msg += \" 约束内最优是 <b>\" + FLUIDS[best.fi].nm + \" + 暂堵 \" + best.fps.toFixed(2) + \"% + 防膨 \" +\r\n        best.stab.toFixed(1) + \"%<\/b>（成本 \" + best.cost.toFixed(2) + \"、滤失 \" + best.fl.toFixed(1) +\r\n        \" mL、恢复值 <b>\" + best.krec.toFixed(1) + \"%<\/b>）\";\r\n      if (gain <= 0.05) {\r\n        msg += \"。当前配方已经不比它差，但自己也踩在预算线上——这时候该做的不是继续加剂量，\" +\r\n          \"而是<b>先把预算这条约束摆到台面上<\/b>，或者接受一个成本更低、恢复率略降的邻近点。\";\r\n      } else {\r\n        msg += \"，比当前配方高 \" + gain.toFixed(1) + \" 个百分点。\";\r\n      }\r\n      if (gain > 6) {\r\n        msg += \" 差距主要来自 <b>\" + MECH[mainIdx].nm + \"<\/b>——这正是不先做配伍剪枝时最容易踩的坑：\" +\r\n          \"体系选错之后，再怎么调添加剂加量也补不回来。\";\r\n      } else if (gain > 0.05 && gain < 1) {\r\n        msg += \" 已经在最优附近了，继续加剂量只会增加成本而不涨恢复值——可以往下看帕累托前沿上更便宜的点。\";\r\n      }\r\n    } else {\r\n      msg += \" 当前预算下<b>没有任何可行配方<\/b>：预算必须放宽到能容纳至少一个体系，或者先接受较高的伤害。\";\r\n    }\r\n    msg += \" 注：这是演示用的降阶伤害模型，绝对值不可用于作业设计，看的是各机理的<b>相对构成<\/b>。\";\r\n    note.innerHTML = msg;\r\n  }\r\n\r\n  [clayIn, tempIn, dpIn, fpsIn, stabIn, bgIn].forEach(function (n) { n.addEventListener(\"input\", draw); });\r\n  draw();\r\n})();\r\n\n<\/script>\r\n<script>(function(){function p(){try{var h=Math.max(document.body?document.body.scrollHeight:0,document.documentElement.scrollHeight);parent.postMessage({__caseDemoH:h},\"*\")}catch(e){}}if(window.ResizeObserver){try{new ResizeObserver(p).observe(document.documentElement)}catch(e){}}window.addEventListener(\"load\",p);setTimeout(p,200);setTimeout(p,900);setTimeout(p,2200)})()<\/script>\n<script>\n(function(){\n  var MIN_OY=3,MIN_OX=2,PAD=2,NUM=/^[0-9.,()%\\s\\/-]+$/;\n  function fixOne(svg){\n    var vb=svg.viewBox&&svg.viewBox.baseVal; if(!vb||!vb.width||vb.width>4000) return;\n    var texts=[].filter.call(svg.querySelectorAll(\"text\"),function(t){\n      return t.textContent.trim()&&!t.getAttribute(\"transform\");\n    });\n    var moved=true,guard=0;\n    while(moved&&guard++<40){\n      moved=false;\n      var bx=texts.map(function(t){ try{ return t.getBBox(); }catch(e){ return null; } });\n      for(var i=0;i<texts.length;i++)for(var j=0;j<texts.length;j++){\n        if(i===j) continue;\n        var ra=bx[i],rb=bx[j];\n        if(!ra||!rb) continue;\n        var a=texts[i],b=texts[j];\n        var ox=Math.min(ra.x+ra.width,rb.x+rb.width)-Math.max(ra.x,rb.x);\n        var oy=Math.min(ra.y+ra.height,rb.y+rb.height)-Math.max(ra.y,rb.y);\n        if(ox<MIN_OX||oy<MIN_OY) continue;\n        if(NUM.test(a.textContent.trim())||NUM.test(b.textContent.trim())) continue;\n        /* 只动 y：b 在 a 下方（或同排且靠右 / 完全叠放的备选标签）时下移错开 */\n        var lower=rb.y-ra.y;\n        var take=lower>0.5||(lower>-0.5&&rb.x>ra.x+0.5)||(Math.abs(lower)<=0.5&&Math.abs(rb.x-ra.x)<=0.5&&j>i);\n        if(!take) continue;\n        var dy=(ra.y+ra.height+PAD)-rb.y;\n        if(dy>0.5){ b.setAttribute(\"y\",((parseFloat(b.getAttribute(\"y\"))||rb.y+rb.height)+dy).toFixed(1)); moved=true; }\n      }\n    }\n    /* 下端是数字刻度、上端是说明标题时：把标题上移，刻度对齐不动 */\n    var bx2=texts.map(function(t){ try{ return t.getBBox(); }catch(e){ return null; } });\n    for(var p=0;p<texts.length;p++)for(var q=0;q<texts.length;q++){\n      if(p===q) continue;\n      var ta=texts[p],tb=texts[q],pa=bx2[p],pb=bx2[q];\n      if(!pa||!pb) continue;\n      if(!NUM.test(tb.textContent.trim())||NUM.test(ta.textContent.trim())) continue;\n      var ox2=Math.min(pa.x+pa.width,pb.x+pb.width)-Math.max(pa.x,pb.x);\n      var oy2=Math.min(pa.y+pa.height,pb.y+pb.height)-Math.max(pa.y,pb.y);\n      if(ox2<MIN_OX||oy2<2) continue;\n      if(pb.y-pa.y>2){ ta.setAttribute(\"y\",((parseFloat(ta.getAttribute(\"y\"))||pa.y+pa.height)-(oy2+1)).toFixed(1)); }\n    }\n    /* 只扩展高度（宽度永远不动，避免整图缩放），把被推出底边的内容装回来 */\n    var maxB=0;\n    [].forEach.call(svg.querySelectorAll(\"text,rect,line,circle,path,polyline,polygon\"),function(el){\n      try{var b2=el.getBBox(); maxB=Math.max(maxB,b2.y+b2.height);}catch(e){}\n    });\n    if(maxB>vb.height-1) svg.setAttribute(\"viewBox\",\"0 0 \"+vb.width+\" \"+Math.ceil(maxB+4));\n  }\n  function fixAll(){ [].forEach.call(document.querySelectorAll(\"svg\"),fixOne); }\n  function boot(){\n    fixAll();\n    if(window.MutationObserver){\n      var mo=new MutationObserver(function(){clearTimeout(fixAll._t);fixAll._t=setTimeout(fixAll,80);});\n      [].forEach.call(document.querySelectorAll(\"svg\"),function(s){mo.observe(s,{childList:true,subtree:true});});\n    }\n  }\n  if(document.readyState===\"loading\") document.addEventListener(\"DOMContentLoaded\",boot); else boot();\n  window.addEventListener(\"load\",function(){setTimeout(fixAll,120);});\n})();\n<\/script>\n<script>\n(function(){\n  function kind(el){\n    var cl=el.classList;\n    if(/^(H1|H2|H3)$/.test(el.tagName)||cl.contains(\"lead\")) return \"head\";\n    if(cl.contains(\"ctl\")) return \"ctl\";\n    if(el.tagName===\"svg\") return \"viz\";\n    if(cl.contains(\"readouts\")||cl.contains(\"tbl\")||el.tagName===\"TABLE\") return \"out\";\n    if(cl.contains(\"note\")||cl.contains(\"legend\")||cl.contains(\"btnrow\")) return \"note\";\n    return \"other\";\n  }\n  function partition(){\n    var root=document.querySelector(\".panel\");\n    if(!root||root.dataset.blkDone) return;\n    root.dataset.blkDone=\"1\";\n    var kids=[].slice.call(root.children);\n    var groups=[],cur=null;\n    kids.forEach(function(el){\n      var k=kind(el);\n      var merge=(cur&&cur.k===k&&(k===\"ctl\"||k===\"viz\"||k===\"note\"));\n      if(merge){cur.els.push(el);}else{groups.push(cur={k:k,els:[el]});}\n    });\n    groups.forEach(function(g){\n      if(g.k===\"ctl\"||g.k===\"viz\"||g.k===\"out\"||g.k===\"note\"){\n        var sec=document.createElement(\"section\");\n        sec.className=\"blk blk-\"+(g.k===\"ctl\"?\"card\":(g.k===\"note\"?\"note\":\"raw\"));\n        g.els[0].parentNode.insertBefore(sec,g.els[0]);\n        g.els.forEach(function(el){sec.appendChild(el);});\n      }\n    });\n  }\n  if(document.readyState===\"loading\") document.addEventListener(\"DOMContentLoaded\",partition); else partition();\n})();\n<\/script>\n<\/body>\r\n<\/html>\r\n";
  function mountDemo(root) {
    var iframe = document.createElement("iframe");
    iframe.setAttribute("sandbox", "allow-scripts allow-forms allow-pointer-lock");
    iframe.setAttribute("title", "可运行示范");
    iframe.style.cssText = "width:100%;border:0;display:block;background:#fbfaf6;border-radius:8px";
    iframe.style.height = 1240 + "px";
    iframe.srcdoc = DEMO_HTML;
    root.appendChild(iframe);
    var onMsg = function (e) {
      var d = e.data || {};
      if (d && d.__caseDemoH && typeof d.h === "number") {
        iframe.style.height = Math.max(320, d.h + 14) + "px";
      }
    };
    window.addEventListener("message", onMsg);
    return function () { window.removeEventListener("message", onMsg); };
  }

  Cases.register({
    id: "completion-fluid-design",
    sceneId: "co5",
    methods: ["kg","opt"],
    title: "完井液体系智能优选与配方设计",
    version: "1.0.0",
    updated: "2026-10-23",
    status: "ready",
    tabs: {"background":{"label":"专业背景","lede":"完井液（射孔液、压井液、砾石充填携砂液）是第一种与储层大面积接触的流体。它与储层不配伍造成的伤害会在投产时就压住产能，而且大部分不可解除。现场通常沿用区块成熟体系，等到发现产能偏低时，伤害已经造成。","judge":[{"label":"数据形态","value":"配方表 + 岩心实验结果","desc":"样本少但结构清晰，含定性配伍规则"},{"label":"标注成本","value":"高","desc":"标签依赖岩心驱替实验，单口井难覆盖多种配方"},{"label":"可见收益","value":"中","desc":"产能恢复率提升直接反映在初期产量上"},{"label":"难度","value":"中","desc":"机理清楚但定量标定难，不同实验室口径不一致"}],"sections":[{"no":1,"en":"PROBLEM","title":"当前做法与问题","html":"<p>常规做法：按区块沿用体系——同一套低固相或清洁盐水体系在本区块用顺了，新井直接照搬，再由现场工程师凭粘土含量与邻井经验调整防膨剂、暂堵剂加量。<\/p><p>问题有三：<b>伤害来源不清<\/b>——投产后产能偏低时，说不清是粘土膨胀、固相侵入、乳化还是结垢，也就无从补救；<b>验证代价高<\/b>——配方的定量依据主要来自岩心驱替实验，单区块只有几十块岩心，覆盖不了全部配方组合；<b>多目标冲突<\/b>——配伍性最好的体系往往最贵、滤失控制最好的配方粘度损失又大。<\/p><div class='viz'><svg viewBox='0 0 700 240' role='img' aria-label='完井液伤害储层的五类机理'>\n<rect x='0' y='0' width='700' height='240' fill='#fbfaf6'/>\n<defs><marker id='arW' markerWidth='6' markerHeight='6' refX='5' refY='3' orient='auto'><path d='M0 0 L6 3 L0 6 Z' fill='#41699b'/><\/marker><\/defs>\n<text x='16' y='17' font-size='11' fill='#242b2e'>完井液会进地层：压差把滤液和固相推进孔隙，产能的损失就来自这里<\/text>\n<rect x='16' y='28' width='300' height='190' rx='6' fill='#efece1' stroke='#e2ded0'/><text x='30' y='48' font-size='10.5' fill='#4d565b'>滤液侵入：压差把液体推进孔隙<\/text>\n<rect x='34' y='64' width='264' height='110' fill='#e3dac7'/><text x='40' y='170' font-size='8.5' fill='#8a7f66'>产层孔隙<\/text>\n<circle cx='70' cy='96' r='4' fill='#8a7f66'/><circle cx='96' cy='88' r='4' fill='#8a7f66'/><circle cx='122' cy='104' r='4' fill='#8a7f66'/><circle cx='150' cy='92' r='4' fill='#8a7f66'/><circle cx='176' cy='110' r='4' fill='#8a7f66'/><circle cx='204' cy='96' r='4' fill='#8a7f66'/><circle cx='232' cy='112' r='4' fill='#8a7f66'/><circle cx='260' cy='98' r='4' fill='#8a7f66'/><circle cx='86' cy='126' r='4' fill='#8a7f66'/><circle cx='114' cy='134' r='4' fill='#8a7f66'/><circle cx='142' cy='124' r='4' fill='#8a7f66'/><circle cx='170' cy='140' r='4' fill='#8a7f66'/><circle cx='198' cy='130' r='4' fill='#8a7f66'/><circle cx='226' cy='144' r='4' fill='#8a7f66'/><circle cx='254' cy='132' r='4' fill='#8a7f66'/><circle cx='100' cy='156' r='4' fill='#8a7f66'/><circle cx='156' cy='160' r='4' fill='#8a7f66'/><circle cx='212' cy='158' r='4' fill='#8a7f66'/>\n<rect x='150' y='64' width='26' height='60' fill='#fff' stroke='#242b2e'/><line x1='150' y1='64' x2='150' y2='124' stroke='#41699b' stroke-width='2'/><line x1='176' y1='64' x2='176' y2='124' stroke='#41699b' stroke-width='2'/>\n<circle cx='110' cy='100' r='3.4' fill='#41699b'/><circle cx='128' cy='112' r='3.4' fill='#41699b'/><circle cx='98' cy='132' r='3.4' fill='#41699b'/><circle cx='116' cy='150' r='3.4' fill='#41699b'/>\n<path d='M136 100 L170 100' stroke='#41699b' stroke-width='1' marker-end='url(#arW)'/><text x='196' y='104' font-size='9' fill='#41699b'>滤液 + 固相<\/text>\n<text x='30' y='196' font-size='9.5' fill='#4d565b'>侵入越深，返排越难；滤饼造得好，侵入就浅。<\/text><text x='30' y='214' font-size='9.5' fill='#79828a'>这就是「暂堵剂加量」这一档参数的物理含义。<\/text>\n<rect x='332' y='28' width='352' height='190' rx='6' fill='#fbfaf6' stroke='#e2ded0'/><text x='346' y='48' font-size='10.5' fill='#4d565b'>五类伤害机理（损失是叠加的）<\/text>\n<text x='346' y='72' font-size='10' fill='#4d565b'>① 粘土水化 / 分散<\/text><text x='346' y='88' font-size='9' fill='#79828a'>滤液让粘土膨胀、运移，堵住喉道<\/text>\n<text x='346' y='108' font-size='10' fill='#4d565b'>② 滤液与固相侵入<\/text><text x='346' y='124' font-size='9' fill='#79828a'>受压差与滤饼封堵率控制<\/text>\n<text x='346' y='144' font-size='10' fill='#4d565b'>③ 乳化 / 润湿反转<\/text><text x='346' y='160' font-size='9' fill='#79828a'>油基体系滤液与地层水乳化<\/text>\n<text x='346' y='180' font-size='10' fill='#4d565b'>④ 结垢 / 化学不配伍<\/text><text x='346' y='196' font-size='9' fill='#79828a'>与地层水离子反应生成沉淀<\/text>\n<text x='346' y='216' font-size='10' fill='#4d565b'>⑤ 高温降解损失<\/text><text x='346' y='230' font-size='9' fill='#c9613f'>超过体系耐温上限后急剧恶化<\/text>\n<\/svg><span class='viz-cap'>左：滤液在压差下侵入孔隙。右：五类伤害机理叠加——只看总恢复率，永远说不清伤害来自哪里。<\/span><\/div>"},{"no":2,"en":"INTERVENTION","title":"AI 能做什么","html":"<p>这个场景有两层。<b>知识图谱<\/b>负责定性部分：把储层敏感性（速敏、水敏、盐敏、酸敏、碱敏）、岩性与各体系的配伍规则、历史作业的成败连成一张图，回答「这口井哪些机理是主要矛盾、什么体系是可用的候选」。<\/p><p>第二层是<b>定量优化<\/b>：用岩心实验数据与机理模型训练一个<b>伤害预测代理模型<\/b>（输入储层条件 + 配方，输出各伤害机理的分量与渗透率恢复值），再在代理模型上按预算与滤失约束做配方寻优，输出<b>候选前沿<\/b>而不是单一配方。<\/p><p>被替掉的是「翻区块配方表 + 等岩心结果」这一环；人仍然要决定接受哪一点——要最好的恢复率还是最便宜的可行配方。<\/p><div class='viz'><svg viewBox='0 0 700 210' role='img' aria-label='知识图谱剪枝加配方寻优两层结构'>\n<rect x='0' y='0' width='700' height='210' fill='#fbfaf6'/>\n<defs><marker id='arX' markerWidth='7' markerHeight='7' refX='6' refY='3' orient='auto'><path d='M0 0 L7 3 L0 6 Z' fill='#242b2e'/><\/marker><\/defs>\n<text x='16' y='17' font-size='11' fill='#242b2e'>两层：知识图谱先剪枝（什么不能用），寻优再在剩下的组合里选（用多少）<\/text>\n<rect x='16' y='30' width='150' height='70' rx='5' fill='#e9e4d8' stroke='#d8d2c4'/><text x='91' y='50' font-size='10.5' fill='#242b2e' text-anchor='middle'>5 种体系<\/text><text x='91' y='68' font-size='9' fill='#79828a' text-anchor='middle'>× 2 种添加剂加量<\/text><text x='91' y='86' font-size='9' fill='#79828a' text-anchor='middle'>= 715 组候选<\/text>\n<path d='M166 65 L200 65' stroke='#242b2e' marker-end='url(#arX)'/>\n<rect x='200' y='30' width='160' height='70' rx='5' fill='#41699b' opacity='0.9'/><text x='280' y='50' font-size='10.5' fill='#fff' text-anchor='middle'>知识图谱剪枝<\/text><text x='280' y='68' font-size='9' fill='#fff' text-anchor='middle'>配伍性 · 耐温上限<\/text><text x='280' y='86' font-size='9' fill='#fff' text-anchor='middle'>滤失上限<\/text>\n<path d='M360 65 L394 65' stroke='#242b2e' marker-end='url(#arX)'/>\n<rect x='394' y='30' width='150' height='70' rx='5' fill='#2f7d6b' opacity='0.9'/><text x='469' y='50' font-size='10.5' fill='#fff' text-anchor='middle'>可行配方集<\/text><text x='469' y='68' font-size='9' fill='#fff' text-anchor='middle'>剪掉超温 / 不配伍<\/text><text x='469' y='86' font-size='9' fill='#fff' text-anchor='middle'>剩下的才参与比选<\/text>\n<path d='M544 65 L578 65' stroke='#242b2e' marker-end='url(#arX)'/>\n<rect x='578' y='30' width='106' height='70' rx='5' fill='#b26a39' opacity='0.9'/><text x='631' y='50' font-size='10.5' fill='#fff' text-anchor='middle'>预算内寻优<\/text><text x='631' y='68' font-size='9' fill='#fff' text-anchor='middle'>成本—恢复率<\/text><text x='631' y='86' font-size='9' fill='#fff' text-anchor='middle'>前沿<\/text>\n<line x1='16' y1='116' x2='684' y2='116' stroke='#e2ded0'/>\n<rect x='16' y='126' width='330' height='70' rx='5' fill='#efece1' stroke='#e2ded0'/><text x='28' y='146' font-size='9.5' fill='#4d565b'>为什么必须剪：体系选错之后，再怎么调添加剂加量<\/text><text x='28' y='164' font-size='9.5' fill='#c9613f'>也补不回来——配伍性是一个乘在各类伤害上的因子。<\/text><text x='28' y='182' font-size='9' fill='#79828a'>先剪枝不只是省算力，更是避免「在不该选的方向上精细优化」。<\/text>\n<rect x='360' y='126' width='324' height='70' rx='5' fill='#dfe6ee' stroke='#d8d2c4'/><text x='372' y='146' font-size='9.5' fill='#41699b'>输出是取舍曲线，不是一个数<\/text><text x='372' y='164' font-size='9' fill='#4d565b'>前沿上每一点都是「花这份钱能拿到的最高恢复率」，<\/text><text x='372' y='182' font-size='9' fill='#4d565b'>预算是多少就取哪一点，预算变了不用重跑。<\/text>\n<\/svg><span class='viz-cap'>知识图谱先做硬约束剪枝，寻优再在可行集里给出成本—恢复率的取舍前沿。<\/span><\/div>"},{"no":3,"en":"DATA","title":"需要准备什么","html":"<p><b>储层与敏感性数据<\/b>：粘土矿物含量与类型（蒙脱石、伊利石、高岭石）、孔渗、地层水矿化度与离子组成、地层压力与温度。<b>这部分决定配伍判据<\/b>。<\/p><p><b>配方数据<\/b>：基液体系、添加剂种类与加量、滤液性质（矿化度、pH、表面张力）、滤失与流变参数——全部结构化，无需标注。<\/p><p><b>实验与作业标签<\/b>：① 岩心驱替实验的<b>渗透率恢复值<\/b>（最核心标签，单区块通常 20–60 块）；② 敏感性评价试验（速敏/水敏/盐敏 程度）；③ 投产后的产能与返排情况，用于事后校验。<\/p><p><b>规格库<\/b>：各体系的耐温上限、添加剂适用浓度窗口与成本——作为优化时的硬约束边界。<\/p><div class='viz'><svg viewBox='0 0 700 190' role='img' aria-label='数据来源与实验口径瓶颈'>\n<rect x='0' y='0' width='700' height='190' fill='#fbfaf6'/>\n<text x='16' y='17' font-size='11' fill='#242b2e'>需要准备什么：实验数据不缺，缺的是口径一致<\/text>\n<rect x='16' y='30' width='200' height='112' rx='5' fill='#e9e4d8' stroke='#d8d2c4'/><text x='116' y='48' font-size='10.5' fill='#242b2e' text-anchor='middle'>岩心驱替实验<\/text>\n<text x='28' y='66' font-size='9' fill='#4d565b'>渗透率恢复率 Krec<\/text><text x='28' y='82' font-size='9' fill='#4d565b'>48 块岩心 · 分机理测定<\/text><line x1='28' y1='94' x2='204' y2='94' stroke='#d8d2c4'/><text x='28' y='110' font-size='9' fill='#c9613f'>驱替程序不同 → 数值不可比<\/text><text x='28' y='130' font-size='9' fill='#c9613f'>单位与围压口径要统一<\/text>\n<rect x='228' y='30' width='200' height='112' rx='5' fill='#dfe6ee' stroke='#d8d2c4'/><text x='328' y='48' font-size='10.5' fill='#242b2e' text-anchor='middle'>储层与流体描述<\/text>\n<text x='240' y='66' font-size='9' fill='#4d565b'>粘土含量 · 矿物组成<\/text><text x='240' y='82' font-size='9' fill='#4d565b'>温度 · 压差 · 地层水离子<\/text><line x1='240' y1='94' x2='416' y2='94' stroke='#d8d2c4'/><text x='240' y='110' font-size='9' fill='#41699b'>来自测井与水分析，结构化<\/text><text x='240' y='130' font-size='9' fill='#41699b'>粘土含量决定敏感档<\/text>\n<rect x='440' y='30' width='244' height='112' rx='5' fill='#e9e4d8' stroke='#d8d2c4'/><text x='562' y='48' font-size='10.5' fill='#242b2e' text-anchor='middle'>配方与成本<\/text>\n<text x='452' y='66' font-size='9' fill='#4d565b'>体系基础成本 · 添加剂单价<\/text><text x='452' y='82' font-size='9' fill='#4d565b'>单方预算上限（管理约束）<\/text><line x1='452' y1='94' x2='672' y2='94' stroke='#d8d2c4'/><text x='452' y='110' font-size='9' fill='#c9613f'>预算不写进约束 → 推荐最贵的体系<\/text><text x='452' y='130' font-size='9' fill='#c9613f'>结果无人采纳，流程被绕开<\/text>\n<rect x='150' y='156' width='400' height='26' rx='5' fill='#2f7d6b' opacity='0.9'/><text x='350' y='173' font-size='10' fill='#fff' text-anchor='middle'>代理模型：48 块岩心标定 + 715 组配方枚举<\/text>\n<path d='M116 142 L116 156' stroke='#c9613f'/><path d='M328 142 L328 156' stroke='#41699b'/><path d='M562 142 L562 156' stroke='#79828a'/>\n<\/svg><span class='viz-cap'>数据分层：实验数据不缺，瓶颈是驱替口径统一；预算必须作为约束写进去。<\/span><\/div>"},{"no":4,"en":"DIFFICULTY","title":"难度与参考方向","html":"<p>难点：<b>恢复率的实验口径不统一<\/b>——不同单位、不同驱替程序给出的同一个配方可能差十几个百分点，跨区块直接合并不成立；<b>机理之间存在耦合<\/b>（提高盐度抑制粘土膨胀，但加剧盐敏与结垢），单靠规则会顾此失彼；<b>成本口径复杂<\/b>——材料费只是一部分，还要计报废处理与占用周期。<\/p><p>改进路线：① 先做统一口径的实验复核，把历史数据按比例因子对齐到一个基准；② 图谱 + 规则先做可行性剪枝（耐温、配伍、预算），再由代理模型在小空间内寻优，避免在不合法区域外推；③ 代理模型优先高斯过程并保留不确定度，让实验室下一个该做的<b>驱替实验<\/b>由贝叶斯优化来选；④ 输出按机理拆分的伤害构成，而不是只给一个恢复率数字。<\/p><div class='viz'><svg viewBox='0 0 700 200' role='img' aria-label='机理掩盖与耐温忽略两个坑'>\n<rect x='0' y='0' width='700' height='200' fill='#fbfaf6'/>\n<text x='16' y='17' font-size='11' fill='#242b2e'>两个最容易踩的坑：机理互相掩盖，以及耐温上限被忽略<\/text>\n<rect x='16' y='28' width='330' height='160' rx='5' fill='#efece1' stroke='#e2ded0'/><text x='28' y='46' font-size='10.5' fill='#4d565b'>① 只看总恢复率：伤害机理互相掩盖<\/text>\n<text x='28' y='66' font-size='9' fill='#79828a'>配方 A<\/text><rect x='80' y='56' width='240' height='16' rx='2' fill='#efece1'/><rect x='80' y='56' width='90' height='16' fill='#41699b'/><rect x='170' y='56' width='110' height='16' fill='#2f7d6b'/><rect x='280' y='56' width='40' height='16' fill='#b26a39'/><text x='80' y='86' font-size='8.5' fill='#4d565b'>水化 37% · 侵入 46% · 乳化 17%　总损失 62%<\/text>\n<text x='28' y='112' font-size='9' fill='#79828a'>配方 B<\/text><rect x='80' y='102' width='240' height='16' rx='2' fill='#efece1'/><rect x='80' y='102' width='180' height='16' fill='#41699b'/><rect x='260' y='102' width='60' height='16' fill='#2f7d6b'/><text x='80' y='132' font-size='8.5' fill='#4d565b'>水化 75% · 侵入 25%　总损失 62%<\/text>\n<text x='28' y='152' font-size='9' fill='#c9613f'>总损失相同，但 B 换到低粘土区块会立刻变差，<\/text><text x='28' y='168' font-size='9' fill='#c9613f'>而 A 不会——只看总数看不出这个差别。<\/text><text x='28' y='184' font-size='9' fill='#79828a'>处理：按机理分量训练，输出构成而不是一个数<\/text>\n<rect x='360' y='28' width='324' height='160' rx='5' fill='#efece1' stroke='#e2ded0'/><text x='372' y='46' font-size='10.5' fill='#4d565b'>② 忽略耐温上限<\/text>\n<line x1='386' y1='150' x2='660' y2='150' stroke='#242b2e'/><line x1='386' y1='62' x2='386' y2='150' stroke='#242b2e'/>\n<path d='M396 140 C 450 136, 500 130, 540 112 C 580 92, 620 76, 656 68' fill='none' stroke='#41699b' stroke-width='2'/><text x='540' y='96' font-size='9' fill='#41699b'>恢复率随温度<\/text>\n<line x1='560' y1='62' x2='560' y2='150' stroke='#c9613f' stroke-dasharray='4 3'/><text x='564' y='76' font-size='8.5' fill='#c9613f'>耐温上限 130 ℃<\/text>\n<text x='520' y='164' font-size='9' fill='#c9613f'>超过上限 → 体系降解失效 → 曲线陡降<\/text>\n<text x='372' y='182' font-size='9' fill='#4d565b'>图纸上配伍性很好，井底却已成为另一种流体。<\/text>\n<\/svg><span class='viz-cap'>左：总恢复率相同但机理构成不同，换区块表现会反转。右：耐温上限越过后体系降解失效。<\/span><\/div>"}]},"workflow":{"label":"案例流程","title":"一口井的完井液配方优选流程","lead":["关键是顺序：先把「不可能 / 不可用」的体系用图谱规则剪掉，再在剩下的小空间里定量寻优。反过来先优化再校核，多半会得到一个打不出来或超预算的配方。","下面的示范就是这个顺序的第 2–4 步：改储层条件或预算，看伤害构成怎么变、以及约束内的最优配方和当前配方差多少。"],"stats":[["候选配方","715 组"],["岩心标定","48 块"],["单方成本","1.00 – 3.20"]],"steps":[{"name":"配伍知识整理成图谱","role":"数据","do":"把敏感性档位、岩性、体系类型、添加剂之间的配伍与禁忌关系录入图谱，附上与实验/作业记录的关联。","effect":"得到可查询的「什么井能用什么体系」规则层，作为后续剪枝依据。","trap":"把配伍规则写成硬约束而不留证据来源，几年后没人知道这条规则从哪来、还成不成立。","viz":"<svg viewBox='0 0 660 120' role='img' aria-label='配伍知识整理成图谱'><rect x='0' y='0' width='660' height='120' fill='#fbfaf6'/><rect x='12' y='30' width='120' height='36' rx='4' fill='#e9e4d8' stroke='#d8d2c4'/><text x='72' y='52' font-size='9.5' fill='#242b2e' text-anchor='middle'>实验室配伍记录<\/text><rect x='12' y='72' width='120' height='30' rx='4' fill='#e9e4d8' stroke='#d8d2c4'/><text x='72' y='91' font-size='9.5' fill='#242b2e' text-anchor='middle'>历史作业结果<\/text><path d='M132 48 L162 60' stroke='#79828a'/><path d='M132 87 L162 68' stroke='#79828a'/><rect x='162' y='42' width='130' height='36' rx='4' fill='#41699b' opacity='0.9'/><text x='227' y='58' font-size='9.5' fill='#fff' text-anchor='middle'>敏感档 × 体系<\/text><text x='227' y='72' font-size='9' fill='#fff' text-anchor='middle'>配伍性矩阵<\/text><path d='M292 60 L322 60' stroke='#242b2e' marker-end='url(#arY)'/><defs><marker id='arY' markerWidth='7' markerHeight='7' refX='6' refY='3' orient='auto'><path d='M0 0 L7 3 L0 6 Z' fill='#242b2e'/><\/marker><\/defs><rect x='322' y='42' width='150' height='36' rx='4' fill='#2f7d6b' opacity='0.9'/><text x='397' y='58' font-size='9.5' fill='#fff' text-anchor='middle'>附历史井次<\/text><text x='397' y='72' font-size='9' fill='#fff' text-anchor='middle'>n&lt;10 提示证据不足<\/text><path d='M472 60 L502 60' stroke='#242b2e' marker-end='url(#arY)'/><rect x='502' y='42' width='146' height='36' rx='4' fill='#c9613f' opacity='0.85'/><text x='575' y='58' font-size='9.5' fill='#fff' text-anchor='middle'>硬约束清单<\/text><text x='575' y='72' font-size='9' fill='#fff' text-anchor='middle'>耐温 / 滤失 / 预算<\/text><rect x='162' y='88' width='486' height='24' rx='4' fill='#efece1' stroke='#e2ded0'/><text x='174' y='104' font-size='9' fill='#4d565b'>图谱里每一格都要带上<tspan font-weight='600'>井次<\/tspan>：配伍性 0.95 但只有 3 井次，与 0.88 但有 31 井次，可信度并不一样<\/text><\/svg>"},{"name":"伤害机理拆分与分量标定","role":"算法","do":"按粘土水化、固相滤液侵入、乳化润湿反转、结垢不配伍、高温降解五类建立分量模型，用岩心数据标定系数。","effect":"预测结果可以按机理拆分，「为什么恢复率低」有具体答案而不是一个数字。","trap":"只拟合总恢复率会让不同机理的贡献互相抵消，换个区块就失准。","viz":"<svg viewBox='0 0 660 120' role='img' aria-label='伤害机理拆分与分量标定'><rect x='0' y='0' width='660' height='120' fill='#fbfaf6'/><text x='12' y='18' font-size='10' fill='#4d565b'>把总损失拆成五个分量：每个分量单独标定，再叠加<\/text><text x='12' y='42' font-size='9' fill='#4d565b'>粘土水化<\/text><rect x='80' y='32' width='200' height='14' rx='2' fill='#efece1'/><rect x='80' y='32' width='86' height='14' fill='#41699b'/><text x='288' y='43' font-size='9' fill='#4d565b'>d = 2.04 · 粘土 · 水化因子 · (1−抑制率)<\/text><text x='12' y='64' font-size='9' fill='#4d565b'>固相侵入<\/text><rect x='80' y='54' width='200' height='14' rx='2' fill='#efece1'/><rect x='80' y='54' width='128' height='14' fill='#2f7d6b'/><text x='288' y='65' font-size='9' fill='#4d565b'>d = 20 · (Δp/25) · 侵入因子 · (1−封堵率)<\/text><text x='12' y='86' font-size='9' fill='#4d565b'>乳化 / 结垢<\/text><rect x='80' y='76' width='200' height='14' rx='2' fill='#efece1'/><rect x='80' y='76' width='58' height='14' fill='#b26a39'/><rect x='138' y='76' width='34' height='14' fill='#c9613f'/><text x='288' y='87' font-size='9' fill='#4d565b'>随体系属性与温度压力变化<\/text><rect x='12' y='96' width='636' height='18' rx='4' fill='#fbfaf6' stroke='#e2ded0'/><text x='24' y='109' font-size='9' fill='#c9613f'>配伍性是一个乘在各类伤害上的因子：体系选错，五个分量同时变大，靠加添加剂补不回来<\/text><\/svg>"},{"name":"训练伤害预测代理模型","role":"算法","do":"用机理模型 + 实验数据训练代理模型，留出实验样本做交叉验证，重点看高伤害区的预测稳定性。","effect":"单次评估降到毫秒，上千组配方的寻优与不确定度传播成为可能。","trap":"实验样本少时必须给出不确定度；只有点估计会让寻优跑到样本稀疏区取到虚假最优。","viz":"<svg viewBox='0 0 660 120' role='img' aria-label='训练伤害预测代理模型'><rect x='0' y='0' width='660' height='120' fill='#fbfaf6'/><text x='12' y='18' font-size='10' fill='#4d565b'>48 块岩心标定，再在 715 组配方上枚举——实验只做代表性点，其余由模型外推<\/text><rect x='12' y='30' width='150' height='40' rx='4' fill='#e9e4d8' stroke='#d8d2c4'/><text x='87' y='48' font-size='9.5' fill='#242b2e' text-anchor='middle'>48 块岩心<\/text><text x='87' y='64' font-size='9' fill='#79828a' text-anchor='middle'>分机理测定<\/text><path d='M162 50 L192 50' stroke='#242b2e' marker-end='url(#arY2)'/><defs><marker id='arY2' markerWidth='7' markerHeight='7' refX='6' refY='3' orient='auto'><path d='M0 0 L7 3 L0 6 Z' fill='#242b2e'/><\/marker><\/defs><rect x='192' y='30' width='150' height='40' rx='4' fill='#41699b' opacity='0.9'/><text x='267' y='48' font-size='9.5' fill='#fff' text-anchor='middle'>分量系数标定<\/text><text x='267' y='64' font-size='9' fill='#fff' text-anchor='middle'>每机理 2–3 个系数<\/text><path d='M342 50 L372 50' stroke='#242b2e' marker-end='url(#arY2)'/><rect x='372' y='30' width='150' height='40' rx='4' fill='#2f7d6b' opacity='0.9'/><text x='447' y='48' font-size='9.5' fill='#fff' text-anchor='middle'>代理模型<\/text><text x='447' y='64' font-size='9' fill='#fff' text-anchor='middle'>毫秒级 · 可枚举<\/text><path d='M522 50 L552 50' stroke='#242b2e' marker-end='url(#arY2)'/><rect x='552' y='30' width='96' height='40' rx='4' fill='#b26a39' opacity='0.85'/><text x='600' y='48' font-size='9.5' fill='#fff' text-anchor='middle'>715 组<\/text><text x='600' y='64' font-size='9' fill='#fff' text-anchor='middle'>候选配方<\/text><rect x='12' y='78' width='636' height='34' rx='4' fill='#efece1' stroke='#e2ded0'/><text x='24' y='94' font-size='9' fill='#4d565b'>留出集校验：48 块里留 8 块不参与标定，只用它评估分量预测的误差。<\/text><text x='24' y='108' font-size='9' fill='#c9613f'>不同驱替程序、不同围压做出的恢复率混着训练 = 模型学到的是实验室而不是储层<\/text><\/svg>"},{"name":"约束剪枝与配方寻优","role":"算法","do":"先用耐温、配伍性、预算、滤失四项硬约束剔除不可行配方，再在余下的组合里求最大恢复率并出帕累托前沿。","effect":"工程师看到的是「成本—恢复率」取舍曲线，预算变了立刻能重选。","trap":"忘记把预算做成显式约束，模型永远推荐最贵的那个体系，实际不会被采纳。","viz":"<svg viewBox='0 0 660 120' role='img' aria-label='约束剪枝与配方寻优'><rect x='0' y='0' width='660' height='120' fill='#fbfaf6'/><text x='12' y='18' font-size='10' fill='#4d565b'>剪枝后剩下的候选，按「成本—恢复率」排帕累托前沿，再由预算定取哪一点<\/text><line x1='30' y1='98' x2='300' y2='98' stroke='#242b2e'/><line x1='30' y1='30' x2='30' y2='98' stroke='#242b2e'/><circle cx='56' cy='88' r='2.4' fill='#b9c6cf'/><circle cx='78' cy='78' r='2.4' fill='#b9c6cf'/><circle cx='104' cy='70' r='2.4' fill='#b9c6cf'/><circle cx='134' cy='60' r='2.4' fill='#b9c6cf'/><circle cx='168' cy='52' r='2.4' fill='#b9c6cf'/><circle cx='206' cy='46' r='2.4' fill='#b9c6cf'/><circle cx='248' cy='42' r='2.4' fill='#b9c6cf'/><circle cx='284' cy='40' r='2.4' fill='#b9c6cf'/><path d='M56 88 C 110 66, 180 46, 284 40' fill='none' stroke='#41699b' stroke-width='1.8'/><line x1='210' y1='30' x2='210' y2='98' stroke='#c9613f' stroke-dasharray='4 3'/><text x='214' y='40' font-size='8.5' fill='#c9613f'>预算上限<\/text><circle cx='196' cy='48' r='5' fill='none' stroke='#2f7d6b' stroke-width='1.6'/><text x='204' y='64' font-size='9' fill='#2f7d6b'>预算内最优<\/text><text x='30' y='112' font-size='8.5' fill='#79828a'>单方成本 →<\/text><rect x='330' y='28' width='318' height='84' rx='4' fill='#efece1' stroke='#e2ded0'/><text x='342' y='46' font-size='9.5' fill='#4d565b'>前沿右侧的点恢复率更高，但超出预算 → 不可行；<\/text><text x='342' y='64' font-size='9.5' fill='#4d565b'>前沿左侧的点更便宜，恢复率略降 → 常常更划算。<\/text><text x='342' y='82' font-size='9' fill='#41699b'>边际收益递减：成本翻一倍往往只换来几个百分点<\/text><text x='342' y='100' font-size='9' fill='#c9613f'>预算收得过紧 → 可行集为空 → 只能接受较高伤害<\/text><\/svg>"},{"name":"实验验证与回填","role":"人工","do":"对本井做一组对比驱替实验或返排跟踪，把实际恢复率回填到图谱与模型，更新该区块的适用性系数。","effect":"区块数据越多，推荐越准；这也是把「实验室口径」逐步统一起来的唯一办法。","trap":"只回填成功的配方、丢掉失败的，模型会退化成「推荐大家都在用的那个」。","viz":"<svg viewBox='0 0 660 120' role='img' aria-label='实验验证与回填'><rect x='0' y='0' width='660' height='120' fill='#fbfaf6'/><rect x='12' y='30' width='112' height='34' rx='4' fill='#41699b' opacity='0.9'/><text x='68' y='51' font-size='9.5' fill='#fff' text-anchor='middle'>推荐配方<\/text><path d='M124 47 L158 47' stroke='#242b2e' marker-end='url(#arY3)'/><defs><marker id='arY3' markerWidth='7' markerHeight='7' refX='6' refY='3' orient='auto'><path d='M0 0 L7 3 L0 6 Z' fill='#242b2e'/><\/marker><\/defs><rect x='158' y='30' width='112' height='34' rx='4' fill='#e9e4d8' stroke='#d8d2c4'/><text x='214' y='51' font-size='9.5' fill='#242b2e' text-anchor='middle'>岩心复验<\/text><path d='M270 47 L304 47' stroke='#242b2e' marker-end='url(#arY3)'/><rect x='304' y='30' width='112' height='34' rx='4' fill='#2f7d6b' opacity='0.9'/><text x='360' y='51' font-size='9.5' fill='#fff' text-anchor='middle'>投产对比<\/text><path d='M416 47 L450 47' stroke='#242b2e' marker-end='url(#arY3)'/><rect x='450' y='30' width='112' height='34' rx='4' fill='#b26a39' opacity='0.85'/><text x='506' y='51' font-size='9.5' fill='#fff' text-anchor='middle'>回填图谱<\/text><path d='M562 47 C 620 47, 626 84, 580 90 C 540 94, 130 96, 68 74' fill='none' stroke='#79828a' stroke-dasharray='4 3'/><rect x='12' y='74' width='300' height='36' rx='4' fill='#efece1' stroke='#e2ded0'/><text x='24' y='90' font-size='9' fill='#4d565b'>只回填「被采纳且验证过」的配方会让成功率虚高；<\/text><text x='24' y='104' font-size='9' fill='#c9613f'>被否掉的方案与原因同样要入库<\/text><rect x='324' y='74' width='324' height='36' rx='4' fill='#dfe6ee' stroke='#d8d2c4'/><text x='336' y='90' font-size='9' fill='#41699b'>靶心指标：预测恢复率 vs 岩心实测的偏差<\/text><text x='336' y='104' font-size='9' fill='#4d565b'>分机理分别统计，某一机理持续偏大 → 该分量系数要重标<\/text><\/svg>"}],"metrics":{"title":"怎么算“做对了”","html":"<p><b>伤害预测精度<\/b>：留出法交叉验证，渗透率恢复值预测的平均绝对误差 ≤ 5 个百分点；更重要的是<b>排序能力<\/b>——按伤害机理归因的 Top-1 与实验判识一致的比例 ≥ 80%。<\/p><p><b>推荐被采纳率<\/b>：推荐配方实际被现场采用的比例，以及采纳井投产后的比采油指数相对同期井的提升。<\/p><p><b>约束遵循<\/b>：推荐配方中超出预算或超滤失限的比例应为 0——这是一票否决项。<\/p>"},"fails":[{"name":"口径不一致直接合并","why":"不同单位、不同驱替程序的恢复率数值混着训练，模型学到的是实验室而不是储层。"},{"name":"只看总恢复率","why":"伤害机理互相掩盖，模型给出的配方在新区块上表现完全相反。"},{"name":"推荐最贵的体系","why":"预算没写进约束，优化目标只盯着恢复率，结果无人采纳，流程被绕开。"},{"name":"忽略耐温上限","why":"体系在高温段降解失效，图纸上配伍性很好，井底却已成为另一种流体。"}]},"demo":{"label":"可运行示范","height":1240,"intro":"改粘土含量、温度、压差与两种添加剂加量，切换体系并调整预算：三张图给出五类伤害机理的构成、知识图谱的「敏感档 × 体系」配伍矩阵与剪枝清单、以及候选配方的成本—恢复率帕累托前沿。","mount":mountDemo,"unmount":function () { if (offDemo) { offDemo(); offDemo = null; } }}},
    imported: false
  });
  var offDemo = null;
  /* 包一层：shell 调用 tabs.demo.mount(root, ctx) */
  var reg = Cases.get("completion-fluid-design");
  if (reg && reg.tabs && reg.tabs.demo) {
    var rawMount = reg.tabs.demo.mount;
    reg.tabs.demo.mount = function (root, ctx) {
      if (offDemo) { offDemo(); offDemo = null; }
      offDemo = rawMount(root, ctx) || null;
    };
  }
})();
